\label{Mthm}
$$\alpha_p(x,y)\leq \left\{\begin{array}{lll} (2-p)\displaystyle\frac{|x-y| \max\{|x|^{p},|y|^{p}\}}
                      {(\max\{|x|,|y|\})} \quad
                      {\rm if}\, \, p\in (-\infty,0) \, \, {\rm and}\, x,y\neq 0;
                    \\   \\(2-p)\displaystyle\frac{|x-y|}
                      {(\max\{|x|,|y|\})^{1-p}} \quad
                      {\rm if}\,\, p\in[0,1] \, \, {\rm and}\,\, x,y\neq 0;\\
                     \\
                       p \,(\max\{|x|,|y|\})^{p-1}|x-y| \quad {\rm if}
                       \,p \, \in(1,\infty)
                     .\end{array}\right.$$

\label{mymaj} For all $x,y \in {\mathbb R}^n$ and $p \in (0,1)$
\begin{equation}
\alpha_p(x,y) \le |{\mathcal A}_{p, 1/p}(x) - {\mathcal A}_{p, 1/p}(y)  | \,,
\end{equation}
and furthermore, if $|x|\le |y|$, we have also
\begin{equation}
\alpha_p(x,y) \le |{\mathcal A}_{p, 1/p}(x) - {\mathcal A}_{p, 1/p}(y)  |
\le
\frac{2}{3^{p}-1}  |{\mathcal A}_{p, 1/p}(x) - {\mathcal A}_{p, 1/p}(z)  |
\end{equation}
where $z$ is as in Theorem \ref{kal}.

Differentiating $f$ with respect to $K$ we get
\begin{eqnarray*}
f^{'}(K)&=&\frac{t^{-2/K}}{K+\log(1/t)}-\frac{t^{-2/K}(K-\log(1/t))}{(K+\log(1/t))^2}
               +\frac{2t^{-2/K}(K-\log(1/t))\log t}{K^2(K+\log(1/t))^2}\\
           	 &=&\frac{2t^{-2/K}(K^2\log(1/t)+K^2\log t-(\log(1/t))^2\log t)}{K^2(K+\log(1/t))^2}\\
        &=&\frac{2t^{-2/K}(\log(1/t))^3}{K^2(K+\log(1/t))^2}>0.
\end{eqnarray*}
For $t=t_0$, $f$ tends to $m_1$ and $1$ when $K$ tends to $1$ and $\infty$,
respectively.\\
For the proof of (2), we differentiate $g$ with respect to $K$ and get,
\begin{eqnarray*}
 g^{'}(K)&=&-\frac{t^{1/K}_0\log(1/t^2_0)}{K^2(1-t^{2/K}_0)}
            -\frac{2t^{3/K}_0\log(1/t^2_0)\log t_0}{K^3(1-t^{2/K}_0)^2}
             -\frac{t^{1/K}_0\log(1/t^2_0)\log t_0}{K^3(1-t^{2/K}_0)}\\
         &=&t^{1/K}_0\log(1/t^2_0)(-K(1-t^{2/K}_0)-(1+t^{2/K}_0)\log t_0)/(K^3(1-t^{2/K}_0)^2)\\
         &=&t^{1/K}_0\log(1/t^2_0)(t^{2/K}_0(1+\log(1/t_0))-(K-\log (1/t_0)))/(K^3(1-t^{2/K}_0)^2)\\
          &=&\frac{t^{3/K}_0\log(1/t^2_0)(1+\log(1/t_0))}{K^3(1-t^{2/K}_0)^2}\left(1-
          \frac{K-\log (1/t_0)}{t^{2/K}_0(1+\log(1/t_0))}\right)>0
\end{eqnarray*}
by (1). We can see that $g$ tends to $m_2$ and
$1$ when $K$ tends to $1$ and $\infty$, respectively. This completes the proof.

The following inequality holds for
$K\geq 1 $ and $t\in[t_0,1),t_0=(e-1)/(e+1)$

\begin{equation}\label{1c}
\log\left(\frac{1+t^{1/K}}{1-t^{1/K}}\right)\leq
K \log\left(\frac{1+t}{1-t}\right).
\end{equation}

The following inequality holds for
$K\geq 1 $ and $t\in(0,t_0],t_0=(e-1)/(e+1)$
\begin{equation}\label{1a}
\log\left(\frac{1+t^{1/K}}{1-t^{1/K}}\right)\leq
K \left(\log\left(\frac{1+t}{1-t}\right)\right)^{1/K}.
\end{equation}

\label{1dd} The following inequality holds for $K\geq 1$, $|z|<1$;
\begin{equation}\label{1dD}
\rho(0,{\mathcal A}_{1/K,K}(z))\leq K\max\{\rho(0,|z|),\rho^{1/K}(0,|z|)\}
\end{equation}
where $\rho$ is the hyperbolic metric \cite[p. 19]{vu1}.

The following inequality holds for $K\geq 1$:
\begin{equation}\label{2i}
\log\left(1+\frac{|{\mathcal A}_{1/K,K}(x)-{\mathcal A}_{1/K,K}(y)|}
{\min\{|{\mathcal A}_{1/K,K}(x)|,|{\mathcal A}_{1/K,K}(y)|\}}\right)
\leq 2^{1-1/K}\max\{\log^{1/K}(t),\log(t)\}
\end{equation}
here $t=1+\displaystyle\frac{|x-y|}{\min\{|x|,|y|\}}$, for all $x,y\in\mathbb{B}^n$.

\rm Properties of ${\mathcal A}:$
\begin{enumerate}

\item For $|x|<1$ and $a,b,c,d>0$
\begin{eqnarray*}
{\mathcal A}_{a,b}({\mathcal A}_{c,d}(x))&=&{\mathcal A}_{a,b}(|x|^{c-1}x)=||x|^{c-1}x|^{a-1}|x|^{c-1}x\\
                       &=&|x|^{ac-c}|x|^{c-1}x=|x|^{ac-1}x.
\end{eqnarray*}
\item For $|x|>1$
\begin{eqnarray*}
{\mathcal A}_{a,b}({\mathcal A}_{c,d}(x))&=&{\mathcal A}_{a,b}(|x|^{d-1}x)=||x|^{d-1}x|^{b-1}|x|^{d-1}x\\
                       &=&|x|^{bd-d}|x|^{d-1}x=|x|^{bd-1}x.
\end{eqnarray*}
(1) and (2) imply that ${\mathcal A}_{a,b}({\mathcal A}_{c,d}(x))={\mathcal A}_{ac,bd}(x)$.
\item ${\mathcal A}^{-1}_{a,b}(x)={\mathcal A}_{1/a,1/b}(x)$.
\end{enumerate}

\cite[(1.5)]{vu1} An inversion in $S^{n-1}(a,r)$ is defined as,
$$h(x)=a+\frac{r^2(x-a)}{|x-a|^2},\; h(a)=\infty, \; h(\infty)=a.$$
Moreover,
\begin{equation}\label{2a}
|h(x)-h(y)|=\frac{r^2|x-y|}{|x-a||y-a|}.
\end{equation}

For the proof of first inequality we observe that
\begin{eqnarray*}
|h(x)-h(z)|&=&|h(x)-\frac{\lambda}{|\lambda|^2} h( x)|=\frac{|\lambda-1|}{\lambda}\frac{r^2}{|x|}\\
   &=&\frac{r^2|x-y|}{|x|(|x|+|x-y|)}\\
   &\leq&\frac{r^2|x-y|}{|x||y|}=|h(x)-h(y)|
\end{eqnarray*}
by triangle inequality.\\
For the second inequality, we have
\begin{eqnarray*}
\frac{|h(x)-h(y)|}{|h(x)-h(z)|}&=&\frac{|x-y|}{|x||y|}\frac{|x|(|x|+|x-y|)}{|x-y|}\\
                                &=&\frac{|x|}{|y|}+\frac{|x-y|}{|y|}\leq 1+\frac{|x|+|y|}{|y|}\leq 3.
\end{eqnarray*}
Note that here equality holds for $x=-y$.

By \cite[Theorem 14.18, (14.4)]{avvb} we get because
 $f:x\mapsto |x|^{K-1}x$ is $K$-quasiconformal \cite[16.2]{v}
$$||x|^{K-1}x,f(0),|y|^{K-1}y,f(\infty)|\leq \eta^{*}_{K,2}(|x,0,y,\infty|)=\eta_{K,2}\left(\frac{|x-y|}{|x|}\right).$$
Finally by \cite[Theorem 10.24]{avvb} and \cite[Remark 10.31]{vu1} we have
\begin{eqnarray*}
||x|^{K-1}x-|y|^{K-1}y|&\leq& |x|^K\eta_{K,2}\left(\frac{|x-y|}{|x|}\right)\\
                        &\leq &\lambda(K)|x|^K\max\{\left(\frac{|x-y|}{x}\right)^{1/K},
                        \left(\frac{|x-y|}{x}\right)^K\}\\
                        &\leq &e^{\pi(K-1/K)}|x|^{K-1/K}\max\{|x-y|^{1/K},|x-y|^K\}.
\end{eqnarray*}

The following inequalities hold for $K\geq 1$;
\begin{equation}\label{2j}
\left|\frac{x}{|x|^{1+1/K}}-\frac{y}{|y|^{1+1/K}}\right|\leq 2^{1-1/K}\frac{|x-y|^{1/K}}{(|x||y|)^{1/K}}
\end{equation}
for all $x,y\in \mathbb{R}^n\setminus\mathbb{B}^n$,

\begin{equation}\label{2k}
\left|\frac{x}{|x|^{1+\beta}}-\frac{y}{|y|^{1+\beta}}\right|\leq \frac{c(K)}{{|x|^{\beta-\alpha}}}
\max\left\{\left(\frac{|x-y|}{|x||y|}\right)^\alpha,\left(\frac{|x-y|}{|x||y|}\right)^\beta\right\}
\end{equation}
for all $x,y\in\mathbb{B}^n$,

\begin{equation}\label{2kk}
\left|\frac{x}{|x|^{1+K}}-\frac{y}{|y|^{1+K}}\right|\leq \frac{e^{\pi(K-1/K)}}{|x|^{K-1/K}}
\max\left\{\left(\frac{|x-y|}{|x||y|}\right)^{1/K},
\left(\frac{|x-y|}{|x||y|}\right)^K\right\}
\end{equation}
for all $x,y\in\mathbb{B}^2$.

\label{ve}
For $p\ge 1$, and $0<d\le 1$ there holds
\begin{equation}\label{bif} \frac{1+p^d}{(2+p)^d-1}\le
\frac{2}{3^d-1}.
\end{equation}

